#[derive(Debug, Clone)]
struct Complex {
    real: i32,
    imag: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Define the machine epsilon
    const EPSILON: i32 = 2;

    // Check if all imaginary parts are close to zero
    let is_all_close_to_zero = arr.iter().all(|c| (c.imag.abs() <= tol * EPSILON));

    if is_all_close_to_zero {
        // Create a new array with imaginary parts set to zero
        arr.iter()
            .map(|c| Complex {
                real: c.real,
                imag: 0,
            })
            .collect()
    } else {
        // Return the input array unchanged
        arr
    }
}

fn main() {
    // Example usage
    let complex_numbers = vec![
        Complex { real: 1, imag: 0 },
        Complex { real: 2, imag: 1 },
        Complex { real: 3, imag: 0 },
    ];
    let tolerance = 1;

    let result = real_if_close(complex_numbers, tolerance);
    for c in result {
        println!("Complex: {} + {}i", c.real, c.imag);
    }
}